// Retire only the plaintext artifacts generated by this preparation before
// encryption was introduced. The current encrypted replacement must exist first.
import {pathToFileURL} from 'node:url';
import {mkdirSync,writeFileSync} from 'node:fs';
const cutoff=41802970302n,branch='release/boutique-tournois-production';
export function legacyPreparationArtifacts(artifacts){
 return artifacts.filter(artifact=>/^preparation-production-[0-9]+$/.test(artifact.name)&&artifact.workflow_run?.head_branch===branch&&BigInt(artifact.workflow_run.id)<=cutoff).map(a=>a.id);
}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){
 const repository=process.env.GITHUB_REPOSITORY,token=process.env.GH_TOKEN;
 if(process.env.ENCRYPTED_ARTIFACT_OUTCOME!=='success'||!repository||!token)throw Error('Remplacement chiffré confirmé et accès GitHub requis.');
 async function api(path,method='GET'){
  const response=await fetch('https://api.github.com/repos/'+repository+path,{method,headers:{authorization:'Bearer '+token,accept:'application/vnd.github+json'},signal:AbortSignal.timeout(30000)});
  if(!response.ok)throw Error('Nettoyage des anciennes archives indisponible.');
  return method==='GET'?response.json():null;
 }
 const selected=[];
 for(let page=1;;page++){
  const result=await api('/actions/artifacts?per_page=100&page='+page);
  selected.push(...legacyPreparationArtifacts(result.artifacts));
  if(result.artifacts.length<100)break;
 }
 for(const id of selected)await api('/actions/artifacts/'+id,'DELETE');
 const result={legacy_preparation_artifacts_removed:selected.length};
 mkdirSync('.production-preparation',{recursive:true,mode:0o700});
 writeFileSync('.production-preparation/legacy-artifact-cleanup.json',JSON.stringify(result)+'\n',{mode:0o600});
 console.log(JSON.stringify(result));
}
